#include <stdio.h>

int main(void) {
    double a, b, c;
    scanf("%lf %lf %lf", &a, &b, &c);
    if (a < b + c && b < a + c && c < a + b) {
        if (a == b && b == c) printf("equilatero\n");
        else if (a == b || a == c || b == c) printf("isosceles\n");
        else printf("escaleno\n");
    } else {
        printf("nao forma triangulo\n");
    }
    return 0;
}

#include <stdio.h>

int main(void) {
    double a, b, c, maior2, lados2;
    scanf("%lf %lf %lf", &a, &b, &c);
    if (a < b + c && b < a + c && c < a + b) {
        if (a >= b && a >= c) { maior2 = a * a; lados2 = b * b + c * c; }
        else if (b >= a && b >= c) { maior2 = b * b; lados2 = a * a + c * c; }
        else { maior2 = c * c; lados2 = a * a + b * b; }
        if (maior2 == lados2) printf("retangulo\n");
        else if (maior2 > lados2) printf("obtusangulo\n");
        else printf("acutangulo\n");
    } else {
        printf("nao forma triangulo\n");
    }
    return 0;
}

#include <stdio.h>

int main(void) {
    int idade;
    double peso, mg = 0;
    scanf("%d %lf", &idade, &peso);
    if (peso < 5.0) {
        printf("nao pode tomar\n");
        return 0;
    }
    if (idade >= 12) {
        mg = (peso >= 60.0) ? 1000.0 : 875.0;
    } else {
        if (peso <= 9.0) mg = 125.0;
        else if (peso <= 16.0) mg = 250.0;
        else if (peso <= 24.0) mg = 375.0;
        else if (peso <= 30.0) mg = 500.0;
        else mg = 750.0;
    }
    printf("%d\n", (int)(mg / 25.0));
    return 0;
}

#include <stdio.h>

int main(void) {
    int dia, mes, ano, vd = 1;
    scanf("%d %d %d", &dia, &mes, &ano);
    if (ano < 1 || mes < 1 || mes > 12 || dia < 1 || dia > 31) {
        vd = 0;
    } else if ((mes == 4 || mes == 6 || mes == 9 || mes == 11) && dia > 30) {
        vd = 0;
    } else if (mes == 2) {
        int bissexto = (ano % 4 == 0 && ano % 100 != 0) || (ano % 400 == 0);
        if (dia > (bissexto ? 29 : 28)) vd = 0;
    }
    printf("%s\n", vd ? "DATA VALIDA" : "DATA INVALIDA");
    return 0;
}

#include <stdio.h>

int main(void) {
    int n;
    double num, maior, menor;
    scanf("%d %lf", &n, &num);
    maior = menor = num;
    for (int i = 1; i < n; i++) {
        scanf("%lf", &num);
        if (num > maior) maior = num;
        if (num < menor) menor = num;
    }
    printf("%.2f\n%.2f\n", maior, menor);
    return 0;
}

#include <stdio.h>

int main(void) {
    int a, b, soma = 0;
    scanf("%d %d", &a, &b);
    for (int i = 0; i < b; i++) {
        soma += a;
    }
    printf("%d\n", soma);
    return 0;
}

#include <stdio.h>

int main(void) {
    long long a1, a2, termo, soma;
    int n;
    scanf("%lld %lld %d", &a1, &a2, &n);
    soma = a1 + a2;
    printf("%lld %lld", a1, a2);
    for (int i = 3; i <= n; i++) {
        termo = a1 + a2;
        printf(" %lld", termo);
        soma += termo;
        a1 = a2;
        a2 = termo;
    }
    printf("\n%lld\n", soma);
    return 0;
}

#include <stdio.h>

int main(void) {
    long long a1, a2, termo;
    int n;
    scanf("%lld %lld %d", &a1, &a2, &n);
    printf("%lld %lld", a1, a2);
    for (int i = 3; i <= n; i++) {
        if (i % 2 == 0) termo = a2 - a1;
        else termo = a2 + a1;
        printf(" %lld", termo);
        a1 = a2;
        a2 = termo;
    }
    printf("\n");
    return 0;
}
